/** Generates a key from the password. */
export async function generateKey(password: Password, options: GenerateKeyOptions): Promise<Key> {
  if (!password?.length) {
    throw new Error("Empty password");
  }

  if (options == null || typeof options !== "object") throw new Error("Bad options");
  if (!(options.algorithm in algorithms))
    throw new Error(`Unknown algorithm: ${options.algorithm}`);

  const algorithm = algorithms[options.algorithm];

  let resultKey: Key["key"];
  let resultSalt: Key["salt"];
  let resultIV: Key["iv"];

  const hmac = options.hmac ?? false;
  // prettier-ignore
  const id = hmac ? { name: "HMAC", hash: algorithm.name } : { name: algorithm.name };
  const usage: KeyUsage[] = hmac ? ["sign", "verify"] : ["encrypt", "decrypt"];

  if (typeof password === "string") {
    if (password.length < options.minPasswordlength) {
      throw new Error(
        `Password string too short (min ${options.minPasswordlength} characters required)`,
      );
    }
    let { salt = "" } = options;
    if (!salt) {
      const { saltBits = 0 } = options;

